import math

def are_equivalent(a, b):
    def sum_of_divisors(n):
        if n == 0:
            return 0
        total = 1
        sqrt_n = int(math.isqrt(n))
        for i in range(2, sqrt_n + 1):
            if n % i == 0:
                total += i
                if i != n // i:
                    total += n // i
        return total

    return sum_of_divisors(a) == sum_of_divisors(b)
